     4→use lighthouse_network::{
     5→    PeerAction, PeerId,
     6→    service::api_types::{
     7→        BlobsByRangeRequestId, BlocksByRangeRequestId, DataColumnsByRangeRequestId,
     8→    },
     9→};
    10→use std::{collections::HashMap, sync::Arc};
    11→use tracing::Span;
    12→use types::{
    13→    BlobSidecar, ChainSpec, ColumnIndex, DataColumnSidecar, DataColumnSidecarList, EthSpec,
    14→    Hash256, RuntimeVariableList, SignedBeaconBlock,
    15→};
    16→
    17→use crate::sync::network_context::MAX_COLUMN_RETRIES;
    18→
    19→/// Accumulates and couples beacon blocks with their associated data (blobs or data columns)
    20→/// from range sync network responses.
    21→///
    22→/// This struct acts as temporary storage while multiple network responses arrive:
    23→/// - Blocks themselves (always required)
    24→/// - Blob sidecars (pre-Fulu fork)
    25→/// - Data columns (Fulu fork and later)
    26→///
    27→/// It accumulates responses until all expected components are received, then couples
    28→/// them together and returns complete `RpcBlock`s ready for processing. Handles validation
    29→/// and peer failure detection during the coupling process.
    30→pub struct RangeBlockComponentsRequest<E: EthSpec> {
    31→    /// Blocks we have received awaiting for their corresponding sidecar.
    32→    blocks_request: ByRangeRequest<BlocksByRangeRequestId, Vec<Arc<SignedBeaconBlock<E>>>>,
    33→    /// Sidecars we have received awaiting for their corresponding block.
    34→    block_data_request: RangeBlockDataRequest<E>,
    35→    /// Span to track the range request and all children range requests.
    36→    pub(crate) request_span: Span,
    37→}
    38→
    39→enum ByRangeRequest<I: PartialEq + std::fmt::Display, T> {
    40→    Active(I),
    41→    Complete(T),
    42→}
    43→
    44→enum RangeBlockDataRequest<E: EthSpec> {
    45→    NoData,
    46→    Blobs(ByRangeRequest<BlobsByRangeRequestId, Vec<Arc<BlobSidecar<E>>>>),
    47→    DataColumns {
    48→        requests: HashMap<
    49→            DataColumnsByRangeRequestId,
    50→            ByRangeRequest<DataColumnsByRangeRequestId, DataColumnSidecarList<E>>,
    51→        >,
    52→        /// The column indices corresponding to the request
    53→        column_peers: HashMap<DataColumnsByRangeRequestId, Vec<ColumnIndex>>,
    54→        expected_custody_columns: Vec<ColumnIndex>,
    55→        attempt: usize,
    56→    },
    57→}
    58→
    59→#[derive(Debug)]
    60→pub(crate) enum CouplingError {
    61→    InternalError(String),
    62→    /// The peer we requested the columns from was faulty/malicious
    63→    DataColumnPeerFailure {
    64→        error: String,
    65→        faulty_peers: Vec<(ColumnIndex, PeerId)>,
    66→        action: PeerAction,
    67→        exceeded_retries: bool,
    68→    },
    69→    BlobPeerFailure(String),
    70→}
    71→
    72→impl<E: EthSpec> RangeBlockComponentsRequest<E> {
    73→    /// Creates a new range request for blocks and their associated data (blobs or data columns).
    74→    ///
    75→    /// # Arguments
    76→    /// * `blocks_req_id` - Request ID for the blocks
    77→    /// * `blobs_req_id` - Optional request ID for blobs (pre-Fulu fork)
    78→    /// * `data_columns` - Optional tuple of (request_id->column_indices pairs, expected_custody_columns) for Fulu fork
    79→    #[allow(clippy::type_complexity)]
    80→    pub fn new(
    81→        blocks_req_id: BlocksByRangeRequestId,
    82→        blobs_req_id: Option<BlobsByRangeRequestId>,
    83→        data_columns: Option<(
    84→            Vec<(DataColumnsByRangeRequestId, Vec<ColumnIndex>)>,
    85→            Vec<ColumnIndex>,
    86→        )>,
    87→        request_span: Span,
    88→    ) -> Self {
    89→        let block_data_request = if let Some(blobs_req_id) = blobs_req_id {
    90→            RangeBlockDataRequest::Blobs(ByRangeRequest::Active(blobs_req_id))
    91→        } else if let Some((requests, expected_custody_columns)) = data_columns {
    92→            let column_peers: HashMap<_, _> = requests.into_iter().collect();
    93→            RangeBlockDataRequest::DataColumns {
    94→                requests: column_peers
    95→                    .keys()
    96→                    .map(|id| (*id, ByRangeRequest::Active(*id)))
    97→                    .collect(),
    98→                column_peers,
    99→                expected_custody_columns,
   100→                attempt: 0,
   101→            }
   102→        } else {
   103→            RangeBlockDataRequest::NoData
   104→        };
   105→
   106→        Self {
   107→            blocks_request: ByRangeRequest::Active(blocks_req_id),
   108→            block_data_request,
   109→            request_span,
   110→        }
   111→    }
   112→
   113→    /// Modifies `self` by inserting a new `DataColumnsByRangeRequestId` for a formerly failed
   114→    /// request for some columns.
   115→    pub fn reinsert_failed_column_requests(
   116→        &mut self,
   117→        failed_column_requests: Vec<(DataColumnsByRangeRequestId, Vec<u64>)>,
   118→    ) -> Result<(), String> {
   119→        match &mut self.block_data_request {
   120→            RangeBlockDataRequest::DataColumns {
   121→                requests,
   122→                expected_custody_columns: _,
   123→                column_peers,
   124→                attempt: _,
   125→            } => {
   126→                for (request, columns) in failed_column_requests.into_iter() {
   127→                    requests.insert(request, ByRangeRequest::Active(request));
   128→                    column_peers.insert(request, columns);
   129→                }
   130→                Ok(())
   131→            }
   132→            _ => Err("not a column request".to_string()),
   133→        }
   134→    }
   135→
   136→    /// Adds received blocks to the request.
   137→    ///
   138→    /// Returns an error if the request ID doesn't match the expected blocks request.
   139→    pub fn add_blocks(
   140→        &mut self,
   141→        req_id: BlocksByRangeRequestId,
   142→        blocks: Vec<Arc<SignedBeaconBlock<E>>>,
   143→    ) -> Result<(), String> {
   144→        self.blocks_request.finish(req_id, blocks)
   145→    }
   146→
   147→    /// Adds received blobs to the request.
   148→    ///
   149→    /// Returns an error if this request expects data columns instead of blobs,
   150→    /// or if the request ID doesn't match.
   151→    pub fn add_blobs(
   152→        &mut self,
   153→        req_id: BlobsByRangeRequestId,
   154→        blobs: Vec<Arc<BlobSidecar<E>>>,
   155→    ) -> Result<(), String> {
   156→        match &mut self.block_data_request {
   157→            RangeBlockDataRequest::NoData => Err("received blobs but expected no data".to_owned()),
   158→            RangeBlockDataRequest::Blobs(req) => req.finish(req_id, blobs),
   159→            RangeBlockDataRequest::DataColumns { .. } => {
   160→                Err("received blobs but expected data columns".to_owned())
   161→            }
   162→        }
   163→    }
   164→
   165→    /// Adds received custody columns to the request.
   166→    ///
   167→    /// Returns an error if this request expects blobs instead of data columns,
   168→    /// or if the request ID is unknown.
   169→    pub fn add_custody_columns(
   170→        &mut self,
   171→        req_id: DataColumnsByRangeRequestId,
   172→        columns: Vec<Arc<DataColumnSidecar<E>>>,
   173→    ) -> Result<(), String> {
   174→        match &mut self.block_data_request {
   175→            RangeBlockDataRequest::NoData => {
   176→                Err("received data columns but expected no data".to_owned())
   177→            }
   178→            RangeBlockDataRequest::Blobs(_) => {
   179→                Err("received data columns but expected blobs".to_owned())
   180→            }
   181→            RangeBlockDataRequest::DataColumns { requests, .. } => {
   182→                let req = requests
   183→                    .get_mut(&req_id)
   184→                    .ok_or(format!("unknown data columns by range req_id {req_id}"))?;
   185→                req.finish(req_id, columns)
   186→            }
   187→        }
   188→    }
   189→
   190→    /// Attempts to construct RPC blocks from all received components.
   191→    ///
   192→    /// Returns `None` if not all expected requests have completed.
   193→    /// Returns `Some(Ok(_))` with valid RPC blocks if all data is present and valid.
   194→    /// Returns `Some(Err(_))` if there are issues coupling blocks with their data.
   195→    pub fn responses(
   196→        &mut self,
   197→        spec: &ChainSpec,
   198→    ) -> Option<Result<Vec<RpcBlock<E>>, CouplingError>> {
   199→        let Some(blocks) = self.blocks_request.to_finished() else {
   200→            return None;
   201→        };
   202→
   203→        // Increment the attempt once this function returns the response or errors
   204→        match &mut self.block_data_request {
   205→            RangeBlockDataRequest::NoData => {
   206→                Some(Self::responses_with_blobs(blocks.to_vec(), vec![], spec))
   207→            }
   208→            RangeBlockDataRequest::Blobs(request) => {
   209→                let Some(blobs) = request.to_finished() else {
   210→                    return None;
   211→                };
   212→                Some(Self::responses_with_blobs(
   213→                    blocks.to_vec(),
   214→                    blobs.to_vec(),
   215→                    spec,
   216→                ))
   217→            }
   218→            RangeBlockDataRequest::DataColumns {
   219→                requests,
   220→                expected_custody_columns,
   221→                column_peers,
   222→                attempt,
   223→            } => {
   224→                let mut data_columns = vec![];
   225→                let mut column_to_peer_id: HashMap<u64, PeerId> = HashMap::new();
   226→                for req in requests.values() {
   227→                    let Some(data) = req.to_finished() else {
   228→                        return None;
   229→                    };
   230→                    data_columns.extend(data.clone())
   231→                }
   232→
   233→                // An "attempt" is complete here after we have received a response for all the
   234→                // requests we made. i.e. `req.to_finished()` returns Some for all requests.
   235→                *attempt += 1;
   236→
   237→                // Note: this assumes that only 1 peer is responsible for a column
   238→                // with a batch.
   239→                for (id, columns) in column_peers {
   240→                    for column in columns {
   241→                        column_to_peer_id.insert(*column, id.peer);
   242→                    }
   243→                }
   244→
   245→                let resp = Self::responses_with_custody_columns(
   246→                    blocks.to_vec(),
   247→                    data_columns,
   248→                    column_to_peer_id,
   249→                    expected_custody_columns,
   250→                    *attempt,
   251→                );
   252→
   253→                if let Err(CouplingError::DataColumnPeerFailure {
   254→                    error: _,
   255→                    faulty_peers,
   256→                    action: _,
   257→                    exceeded_retries: _,
   258→                }) = &resp
   259→                {
   260→                    for (_, peer) in faulty_peers.iter() {
   261→                        // find the req id associated with the peer and
   262→                        // delete it from the entries as we are going to make
   263→                        // a separate attempt for those components.
   264→                        requests.retain(|&k, _| k.peer != *peer);
   265→                    }
   266→                }
   267→
   268→                Some(resp)
   269→            }
   270→        }
   271→    }
   272→
   273→    fn responses_with_blobs(
   274→        blocks: Vec<Arc<SignedBeaconBlock<E>>>,
   275→        blobs: Vec<Arc<BlobSidecar<E>>>,
   276→        spec: &ChainSpec,
   277→    ) -> Result<Vec<RpcBlock<E>>, CouplingError> {
   278→        // There can't be more more blobs than blocks. i.e. sending any blob (empty
   279→        // included) for a skipped slot is not permitted.
   280→        let mut responses = Vec::with_capacity(blocks.len());
   281→        let mut blob_iter = blobs.into_iter().peekable();
   282→        for block in blocks.into_iter() {
   283→            let max_blobs_per_block = spec.max_blobs_per_block(block.epoch()) as usize;
   284→            let mut blob_list = Vec::with_capacity(max_blobs_per_block);
   285→            while {
   286→                blob_iter
   287→                    .peek()
   288→                    .map(|sidecar| sidecar.slot() == block.slot())
   289→                    .unwrap_or(false)
   290→            } {
   291→                blob_list.push(blob_iter.next().ok_or_else(|| {
   292→                    CouplingError::BlobPeerFailure("Missing next blob".to_string())
   293→                })?);
   294→            }
   295→
   296→            let mut blobs_buffer = vec![None; max_blobs_per_block];
   297→            for blob in blob_list {
   298→                let blob_index = blob.index as usize;
   299→                let Some(blob_opt) = blobs_buffer.get_mut(blob_index) else {
   300→                    return Err(CouplingError::BlobPeerFailure(
   301→                        "Invalid blob index".to_string(),
   302→                    ));
   303→                };
   304→                if blob_opt.is_some() {
   305→                    return Err(CouplingError::BlobPeerFailure(
   306→                        "Repeat blob index".to_string(),
   307→                    ));
   308→                } else {
   309→                    *blob_opt = Some(blob);
   310→                }
   311→            }
   312→            let blobs = RuntimeVariableList::new(
   313→                blobs_buffer.into_iter().flatten().collect::<Vec<_>>(),
   314→                max_blobs_per_block,
   315→            )
   316→            .map_err(|_| {
   317→                CouplingError::BlobPeerFailure("Blobs returned exceeds max length".to_string())
   318→            })?;
   319→            responses.push(
   320→                RpcBlock::new(None, block, Some(blobs))
   321→                    .map_err(|e| CouplingError::BlobPeerFailure(format!("{e:?}")))?,
   322→            )
   323→        }
   324→
   325→        // if accumulated sidecars is not empty, log an error but return the responses
   326→        // as we can still make progress.
   327→        if blob_iter.next().is_some() {
   328→            tracing::debug!(
   329→                remaining_blobs=?blob_iter.collect::<Vec<_>>(),
   330→                "Received sidecars that don't pair well",
   331→            );
   332→        }
   333→
   334→        Ok(responses)
   335→    }
   336→
   337→    fn responses_with_custody_columns(
   338→        blocks: Vec<Arc<SignedBeaconBlock<E>>>,
   339→        data_columns: DataColumnSidecarList<E>,
   340→        column_to_peer: HashMap<u64, PeerId>,
   341→        expects_custody_columns: &[ColumnIndex],
   342→        attempt: usize,
   343→    ) -> Result<Vec<RpcBlock<E>>, CouplingError> {
   344→        // Group data columns by block_root and index
   345→        let mut data_columns_by_block =
   346→            HashMap::<Hash256, HashMap<ColumnIndex, Arc<DataColumnSidecar<E>>>>::new();
   347→
   348→        for column in data_columns {
   349→            let block_root = column.block_root();
   350→            let index = column.index;
   351→            if data_columns_by_block
   352→                .entry(block_root)
   353→                .or_default()
   354→                .insert(index, column)
   355→                .is_some()
   356→            {
   357→                // `DataColumnsByRangeRequestItems` ensures that we do not request any duplicated indices across all peers
   358→                // we request the data from.
   359→                // If there are duplicated indices, its likely a peer sending us the same index multiple times.
   360→                // However we can still proceed even if there are extra columns, just log an error.
   361→                tracing::debug!(?block_root, ?index, "Repeated column for block_root");
   362→                continue;
   363→            }
   364→        }
   365→
   366→        // Now iterate all blocks ensuring that the block roots of each block and data column match,
   367→        // plus we have columns for our custody requirements
   368→        let mut rpc_blocks = Vec::with_capacity(blocks.len());
   369→
   370→        let exceeded_retries = attempt >= MAX_COLUMN_RETRIES;
   371→        for block in blocks {
   372→            let block_root = get_block_root(&block);
   373→            rpc_blocks.push(if block.num_expected_blobs() > 0 {
   374→                let Some(mut data_columns_by_index) = data_columns_by_block.remove(&block_root)
   375→                else {
   376→                    let responsible_peers = column_to_peer.iter().map(|c| (*c.0, *c.1)).collect();
   377→                    return Err(CouplingError::DataColumnPeerFailure {
   378→                        error: format!("No columns for block {block_root:?} with data"),
   379→                        faulty_peers: responsible_peers,
   380→                        action: PeerAction::LowToleranceError,
   381→                        exceeded_retries,
   382→
   383→                    });
   384→                };
   385→
   386→                let mut custody_columns = vec![];
   387→                let mut naughty_peers = vec![];
   388→                for index in expects_custody_columns {
   389→                    // Safe to convert to `CustodyDataColumn`: we have asserted that the index of
   390→                    // this column is in the set of `expects_custody_columns` and with the expected
   391→                    // block root, so for the expected epoch of this batch.
   392→                    if let Some(data_column) = data_columns_by_index.remove(index) {
   393→                        custody_columns.push(CustodyDataColumn::from_asserted_custody(data_column));
   394→                    } else {
   395→                        let Some(responsible_peer) = column_to_peer.get(index) else {
   396→                            return Err(CouplingError::InternalError(format!("Internal error, no request made for column {}", index)));
   397→                        };
   398→                        naughty_peers.push((*index, *responsible_peer));
   399→                    }
   400→                }
   401→                if !naughty_peers.is_empty() {
   402→                    return Err(CouplingError::DataColumnPeerFailure {
   403→                        error: format!("Peers did not return column for block_root {block_root:?} {naughty_peers:?}"),
   404→                        faulty_peers: naughty_peers,
   405→                        action: PeerAction::LowToleranceError,
   406→                        exceeded_retries
   407→                    });
   408→                }
   409→
   410→                // Assert that there are no columns left
   411→                if !data_columns_by_index.is_empty() {
   412→                    let remaining_indices = data_columns_by_index.keys().collect::<Vec<_>>();
   413→                    // log the error but don't return an error, we can still progress with extra columns.
   414→                    tracing::debug!(
   415→                        ?block_root,
   416→                        ?remaining_indices,
   417→                        "Not all columns consumed for block"
   418→                    );
   419→                }
   420→
   421→                RpcBlock::new_with_custody_columns(Some(block_root), block, custody_columns)
   422→                    .map_err(|e| CouplingError::InternalError(format!("{:?}", e)))?
   423→            } else {
   424→                // Block has no data, expects zero columns
   425→                RpcBlock::new_without_blobs(Some(block_root), block)
   426→            });
   427→        }
   428→
   429→        // Assert that there are no columns left for other blocks
   430→        if !data_columns_by_block.is_empty() {
   431→            let remaining_roots = data_columns_by_block.keys().collect::<Vec<_>>();
   432→            // log the error but don't return an error, we can still progress with responses.
   433→            // this is most likely an internal error with overrequesting or a client bug.
   434→            tracing::debug!(?remaining_roots, "Not all columns consumed for block");
   435→        }
   436→
   437→        Ok(rpc_blocks)
   438→    }
   439→}
   440→
   441→impl<I: PartialEq + std::fmt::Display, T> ByRangeRequest<I, T> {
   442→    fn finish(&mut self, id: I, data: T) -> Result<(), String> {
   443→        match self {
   444→            Self::Active(expected_id) => {
   445→                if expected_id != &id {
   446→                    return Err(format!("unexpected req_id expected {expected_id} got {id}"));
   447→                }
   448→                *self = Self::Complete(data);
   449→                Ok(())
   450→            }
   451→            Self::Complete(_) => Err("request already complete".to_owned()),
   452→        }
   453→    }
   454→
   455→    fn to_finished(&self) -> Option<&T> {
   456→        match self {
   457→            Self::Active(_) => None,
   458→            Self::Complete(data) => Some(data),
   459→        }
   460→    }
   461→}
