   669→            None,
   670→            Some((columns_req_id.clone(), expects_custody_columns.clone())),
   671→            Span::none(),
   672→        );
   673→
   674→        let mut rng = XorShiftRng::from_seed([42; 16]);
   675→        let blocks = (0..4)
   676→            .map(|_| {
   677→                generate_rand_block_and_data_columns::<E>(
   678→                    ForkName::Fulu,
   679→                    NumBlobs::Number(1),
   680→                    &mut rng,
   681→                    &spec,
   682→                )
   683→            })
   684→            .collect::<Vec<_>>();
   685→
   686→        // Send blocks and complete terminate response
   687→        info.add_blocks(
   688→            blocks_req_id,
   689→            blocks.iter().map(|b| b.0.clone().into()).collect(),
   690→        )
   691→        .unwrap();
   692→        // Assert response is not finished
   693→        assert!(!is_finished(&mut info));
   694→
   695→        for (i, column_indices) in batched_column_requests.iter().enumerate() {
   696→            let (req, _columns) = columns_req_id.get(i).unwrap();
   697→            // Send the set of columns in the same batch request
   698→            info.add_custody_columns(
   699→                *req,
   700→                blocks
   701→                    .iter()
   702→                    .flat_map(|b| {
   703→                        b.1.iter()
   704→                            .filter(|d| column_indices.contains(&d.index))
   705→                            .cloned()
   706→                    })
   707→                    .collect::<Vec<_>>(),
   708→            )
   709→            .unwrap();
   710→
   711→            if i < num_of_data_column_requests - 1 {
   712→                assert!(
   713→                    !is_finished(&mut info),
   714→                    "requested should not be finished at loop {i}"
   715→                );
   716→            }
   717→        }
   718→
   719→        // All completed construct response
   720→        info.responses(&spec).unwrap().unwrap();
   721→    }
